public struct Node { public int value; public int next; }   // next = -1 — конец

public sealed class IndexList {
    Node[] nodes = new Node[16];
    int count;              // сколько ячеек выдано за всё время
    int free = -1;          // голова свободного списка
    public int Head = -1;

    public int PushFront(int value) {
        int i;
        if (free != -1) { i = free; free = nodes[i].next; }   // переиспользуем ячейку
        else {
            if (count == nodes.Length) Array.Resize(ref nodes, count * 2);
            i = count++;
        }
        nodes[i] = new Node { value = value, next = Head };
        Head = i;
        return i;
    }
    public void PopFront() {
        int i = Head;
        Head = nodes[i].next;
        nodes[i].next = free; free = i;                        // ячейку — в свободный список
    }
}
